import{cohortLabels}from'./current-match-chart.js';
const $=id=>document.getElementById(id),h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
try{const response=await fetch('./current-match-review-data.json',{cache:'no-store'});if(!response.ok)throw Error('Could not load the current review.');const data=await response.json();
$('status').textContent='Current replay · '+new Date(data.generatedAt).toLocaleDateString('en-US',{timeZone:'America/Chicago',year:'numeric',month:'long',day:'numeric'});
$('checks').innerHTML='<p><strong>1,000 base profiles</strong> · 172 preserved original profiles + 828 structured synthetic cases. Twelve diagnostic variants are outside that denominator. Six owner-only profiles stay authenticated.</p><p><strong>No display-text classification.</strong> Numeric ratings and selected question/option IDs drive matching. The simulator uses frozen topic, method and responsibility IDs. Unknown specialist preferences remain unfamiliar.</p><p><strong>Original inputs preserved:</strong> '+data.fixes.originalAnswersRewritten+' rewritten. '+data.fixes.inferredClaimsHeld+' reviewed development-side inferred claims have a hold on uncertain evidence. '+data.fixes.holdoutSpecificHolds+' holdout-specific holds.</p>';
const ratio=(n,d)=>n+' / '+d+' ('+(100*n/d).toFixed(1)+'%)',sum=(cs,extra)=>cs.filter(c=>extra?['development056','holdout056'].includes(c.phase):!['development056','holdout056','diagnostic049'].includes(c.phase)).reduce((a,c)=>({n:a.n+c.models,top:a.top+c.top,degree:a.degree+c.degreeTop}),{n:0,top:0,degree:0});
const correction=data.replayCorrection;if(correction){const original=sum(correction.currentCohorts,false),priorAdded=sum(correction.previousCohorts,true),added=sum(correction.currentCohorts,true),before=correction.originalBeforeEvidenceHolds;
$('correction').innerHTML='<p>The withdrawn replay capped added profiles at three career comparisons and misclassified guided professions’ Yes/No controls as activity checkboxes. Those defining responses were not recorded. The corrected replay dispatches by question kind and covers every mapped subject-aligned career, reusing shared activity answers.</p><div class="table-scroll"><table><thead><tr><th>Comparable group</th><th>Supported Top</th><th>College / graduate Top</th></tr></thead><tbody>'+(before?'<tr><th>Original 172 · before evidence holds</th><td>'+ratio(before.top,before.models)+'</td><td>'+ratio(before.degreeTop,before.models)+'</td></tr>':'')+'<tr><th>Original 172 · current, unchanged by replay correction</th><td>'+ratio(original.top,original.n)+'</td><td>'+ratio(original.degree,original.n)+'</td></tr><tr><th>Added 828 · withdrawn incomplete replay</th><td>'+ratio(priorAdded.top,priorAdded.n)+'</td><td>'+ratio(priorAdded.degree,priorAdded.n)+'</td></tr><tr><th>Added 828 · corrected comprehensive replay</th><td>'+ratio(added.top,added.n)+'</td><td>'+ratio(added.degree,added.n)+'</td></tr></tbody></table></div><p>Profiles, answer bindings, numerical scoring and Top support requirements are unchanged. No degree bonus or match-rate target was introduced. This measures comprehensive relevant-question coverage, not typical student completion or independently validated accuracy.</p>';}
const expansion=data.bindingExpansion006;if(expansion){const beforeByPhase=new Map(expansion.beforeCohorts.map(c=>[c.phase,c])),afterByPhase=new Map(expansion.afterCohorts.map(c=>[c.phase,c]));const stages=[['Public base cohort',expansion.before,expansion.after],...['development056','holdout056'].map(phase=>[cohortLabels[phase],beforeByPhase.get(phase),afterByPhase.get(phase)])];
$('binding-results').innerHTML='<p>Added explicit simulation bindings for 49 previously unmapped professions, including software, testing, GIS, health education, creative writing and archives. Ten technology activity options now have direct bindings. Frozen profiles, the official 60 answers, numerical scoring, support requirements and first-three Top definition are unchanged.</p><div class="table-scroll"><table><thead><tr><th>Same cohort</th><th>Supported Top · before → now</th><th>College / graduate Top · before → now</th></tr></thead><tbody>'+stages.map(([label,b,a])=>'<tr><th>'+h(label)+'</th><td>'+ratio(b.top,b.models)+' → '+ratio(a.top,a.models)+'</td><td>'+ratio(b.degreeTop,b.models)+' → '+ratio(a.degreeTop,a.models)+'</td></tr>').join('')+'</tbody></table></div><p>The 628-profile development rehearsal ran first. The new bindings were frozen before the separate 200-profile holdout evaluation. No model was edited to reach a match quota. This is better simulator coverage, not evidence of independently validated matching accuracy.</p><details><summary>Review the 23 development models gaining their first Top</summary><p>Author review of stated interests and responsibilities; these are not independent reviews. Broad correlations can be negative or unavailable even when specific learning interests are supported.</p><div class="table-scroll"><table><thead><tr><th>Model</th><th>Current Top</th><th>Why the specific interests fit / limits</th></tr></thead><tbody>'+expansion.mappingReview.developmentFirstTopReviews.map(r=>'<tr><th><a href="./model-match-chart.html?query='+encodeURIComponent(r.id)+'">'+h(r.name)+' →</a><small>'+h(r.id)+'</small></th><td>'+r.top.map(p=>h(p.title)+'<small>Broad correlation: '+(Number.isFinite(p.r)?p.r.toFixed(3):'unavailable')+'</small>').join('<br>')+'</td><td>'+h(r.reason)+'</td></tr>').join('')+'</tbody></table></div></details>';}
$('cohorts').innerHTML=data.cohorts.map(c=>'<tr><th>'+h(cohortLabels[c.phase]||c.phase)+'</th><td>'+c.models+'</td><td>'+c.top+'</td><td>'+c.degreeTop+'</td><td>'+c.topCovers+'</td><td>'+c.noTop+'</td></tr>').join('');
$('limits').innerHTML='<p>Explicit simulation bindings cover <strong>'+data.simulation.bindingCoverage.mappedCareers+' of '+data.simulation.bindingCoverage.accessibleCareers+' careers</strong> ('+data.simulation.bindingCoverage.mappedSpecificQuestions+' profession questions and '+data.simulation.bindingCoverage.mappedOptions+' task options). A missing Top match can reflect an unstated preference, an unvisited comparison or an unmapped career. These are separate from a genuine interest mismatch.</p><p>The 828 added profiles have not received independent qualitative case review. Their response generator reuses authored career constructs and existing option-to-career mappings. This tests software behavior and coverage; it does not independently validate matching quality.</p><p>The original 30, fresh 12 and additional 200 holdouts have separate result rows and no case-specific tuning in this change. Earlier aggregate outcomes were seen during the withdrawn simulator runs. The additional holdout is therefore <strong>not an untouched final validation set</strong>.</p><p>Original profiles retain '+data.fixes.remainingOriginalHoldoutFlags+' previously flagged Top claims in untouched holdout cases. '+data.fixes.newTopClaimsAwaitingIndependentReview+' new original-profile Top claims still need qualitative review. A larger synthetic cohort does not resolve those flags.</p>';
const render=()=>{const mode=$('filter').value,q=$('search').value.trim().toLowerCase(),rows=data.rows.filter(r=>(mode==='all'||mode==='no-top'&&r.noTop||mode==='no-degree'&&r.noDegreeTop||mode==='held'&&r.heldClaims.length||mode==='flags'&&r.unresolvedTopFlags.length)&&(r.id+' '+r.name).toLowerCase().includes(q));$('count').textContent=rows.length+' original profiles in this review';$('cases').innerHTML=rows.map(r=>'<tr><th><a href="./model-match-chart.html?query='+encodeURIComponent(r.id)+'">'+h(r.name)+' →</a><small>'+h(r.id+' · '+(cohortLabels[r.phase]||r.phase))+'</small></th><td>'+(r.top.map(p=>h(p.title)+(p.degree?' · degree route':'')+'<small>'+h(p.reviewStatus)+'</small>').join('<br>')||'No supported Top match')+'</td><td>'+r.heldClaims.map(p=>'<p><strong>'+h(p.id)+'</strong> · '+h(p.reason)+'</p>').join('')+r.unresolvedTopFlags.map(p=>'<p><strong>Untouched holdout flag: '+h(p.title)+'</strong> · '+h(p.reason)+'</p>').join('')+(!r.heldClaims.length&&!r.unresolvedTopFlags.length?'<p>'+h(r.noTopReview?.verdict||r.summary||'No new case-level conclusion; inspect the recorded answers.')+'</p>':'')+'</td></tr>').join('');};$('filter').onchange=render;$('search').oninput=render;render();
}catch(e){$('status').textContent=e.message;}
